def process(omni2Ap, smaChangeHourly) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    ap = omni2Ap.copy()
    drag = smaChangeHourly.copy()

    ap['time'] = pd.to_datetime(ap['time'], utc=True, errors='coerce')
    drag['epochHour'] = pd.to_datetime(drag['epochHour'], utc=True, errors='coerce')

    ap = ap.dropna(subset=['time']).sort_values('time')
    drag = drag.dropna(subset=['epochHour']).sort_values('epochHour')

    ap_series = pd.Series(pd.to_numeric(ap['ap'], errors='coerce').values, index=ap['time'])
    drag_series = pd.Series(pd.to_numeric(drag['deltaA_km'], errors='coerce').values, index=drag['epochHour'])

    # Restrict to May 1-30, 2024 hourly window
    start = pd.Timestamp('2024-05-01T00:00:00Z')
    end = pd.Timestamp('2024-05-31T00:00:00Z')
    idx = pd.date_range(start, end, freq='h', inclusive='left')

    ap_series = ap_series.reindex(idx)
    drag_series = drag_series.reindex(idx)

    best = {'lagHours': None, 'n': 0, 'r2': np.nan}

    for lag in range(0, 49):
        ap_lagged = ap_series.shift(lag)  # ap(t-lag)
        mask = drag_series.notna() & ap_lagged.notna()
        n = int(mask.sum())
        if n < 3:
            r2 = np.nan
        else:
            r = np.corrcoef(drag_series[mask].astype(float), ap_lagged[mask].astype(float))[0, 1]
            r2 = float(r * r) if np.isfinite(r) else np.nan

        if np.isnan(best['r2']):
            if not np.isnan(r2):
                best = {'lagHours': lag, 'n': n, 'r2': r2}
        else:
            if (not np.isnan(r2)) and (r2 > best['r2'] + 1e-15):
                best = {'lagHours': lag, 'n': n, 'r2': r2}

    return pd.DataFrame([best])
